/** Error raised for invalid table input. */
export class TableError extends Error {
  /**
   * @param {string} code Stable machine-readable reason.
   * @param {string} message Human-readable detail.
   */
  constructor(code, message) {
    super(message);
    this.name = 'TableError';
    this.code = code;
  }
}

const ZERO_WIDTH_CODE_POINTS = new Set([
  0x200b,
  0x200c,
  0x200d,
  0xfeff,
]);

const WIDE_RANGES = [
  [0x1100, 0x115f],
  [0x2e80, 0x303e],
  [0x3041, 0x33ff],
  [0x3400, 0x4dbf],
  [0x4e00, 0x9fff],
  [0xa000, 0xa4cf],
  [0xac00, 0xd7a3],
  [0xf900, 0xfaff],
  [0xfe10, 0xfe19],
  [0xfe30, 0xfe6f],
  [0xff00, 0xff60],
  [0xffe0, 0xffe6],
  [0x1f300, 0x1f64f],
  [0x1f900, 0x1f9ff],
  [0x20000, 0x2fffd],
  [0x30000, 0x3fffd],
];

/**
 * Return the terminal-column width of one Unicode code point.
 *
 * @param {number} codePoint Unicode code point.
 * @returns {number} Zero, one, or two columns.
 */
function codePointWidth(codePoint) {
  if (
    codePoint < 0x20 ||
    codePoint === 0x7f ||
    ZERO_WIDTH_CODE_POINTS.has(codePoint) ||
    (codePoint >= 0x0300 && codePoint <= 0x036f)
  ) {
    return 0;
  }

  for (const [start, end] of WIDE_RANGES) {
    if (codePoint >= start && codePoint <= end) {
      return 2;
    }
  }

  return 1;
}

/**
 * Validate a cell value.
 *
 * @param {unknown} text Value to validate.
 */
function validateCell(text) {
  if (typeof text !== 'string') {
    throw new TableError('BAD_CELL', 'cell must be a string');
  }
}

/**
 * Validate a column width.
 *
 * @param {unknown} width Value to validate.
 */
function validateWidth(width) {
  if (!Number.isInteger(width) || width < 1) {
    throw new TableError('BAD_WIDTH', 'width must be a positive integer');
  }
}

/**
 * Display width of a string in terminal columns.
 *
 * @param {string} text Text to measure.
 * @returns {number} Column count.
 */
export function stringWidth(text) {
  validateCell(text);

  let width = 0;
  for (const character of text) {
    width += codePointWidth(character.codePointAt(0));
  }
  return width;
}

/**
 * Split one explicit-line piece into words separated by literal spaces.
 *
 * @param {string} piece Text without a newline.
 * @returns {string[]} Non-empty words.
 */
function wordsInPiece(piece) {
  const words = [];
  let word = '';
  let hasWord = false;

  for (const character of piece) {
    if (character === ' ') {
      if (hasWord) {
        words.push(word);
        word = '';
        hasWord = false;
      }
    } else {
      word += character;
      hasWord = true;
    }
  }

  if (hasWord) {
    words.push(word);
  }
  return words;
}

/**
 * Break an over-long word into display-width-limited chunks.
 *
 * @param {string} word Word to break.
 * @param {number} width Maximum chunk width.
 * @returns {string[]} Word chunks.
 */
function breakWord(word, width) {
  const chunks = [];
  let chunk = '';
  let chunkWidth = 0;

  for (const character of word) {
    const characterWidth = codePointWidth(character.codePointAt(0));
    if (characterWidth > width) {
      throw new TableError('UNWRAPPABLE', 'character is wider than the column');
    }

    if (chunkWidth + characterWidth > width) {
      chunks.push(chunk);
      chunk = character;
      chunkWidth = characterWidth;
    } else {
      chunk += character;
      chunkWidth += characterWidth;
    }
  }

  if (chunk !== '' || chunks.length === 0) {
    chunks.push(chunk);
  }
  return chunks;
}

/**
 * Wrap one piece without its explicit newline.
 *
 * @param {string} piece Text without a newline.
 * @param {number} width Maximum line width.
 * @returns {string[]} Wrapped lines.
 */
function wrapPiece(piece, width) {
  const words = wordsInPiece(piece);
  if (words.length === 0) {
    return [''];
  }

  const lines = [];
  let line = '';
  let lineWidth = 0;
  let lineHasContent = false;

  for (const word of words) {
    const chunks = breakWord(word, width);

    for (let chunkIndex = 0; chunkIndex < chunks.length; chunkIndex += 1) {
      const chunk = chunks[chunkIndex];
      const chunkWidth = stringWidth(chunk);

      if (chunkIndex === 0) {
        if (!lineHasContent) {
          line = chunk;
          lineWidth = chunkWidth;
          lineHasContent = true;
        } else if (lineWidth + 1 + chunkWidth <= width) {
          line += ` ${chunk}`;
          lineWidth += 1 + chunkWidth;
        } else {
          lines.push(line);
          line = chunk;
          lineWidth = chunkWidth;
          lineHasContent = true;
        }
      } else if (lineWidth + chunkWidth <= width) {
        line += chunk;
        lineWidth += chunkWidth;
      } else {
        lines.push(line);
        line = chunk;
        lineWidth = chunkWidth;
        lineHasContent = true;
      }
    }
  }

  if (lineHasContent) {
    lines.push(line);
  } else {
    lines.push('');
  }
  return lines;
}

/**
 * Wrap cell text to a column width.
 *
 * @param {string} text Cell text; explicit newlines start a new line.
 * @param {number} width Column width in display columns.
 * @returns {string[]} Wrapped lines, at least one.
 */
export function wrapCell(text, width) {
  validateCell(text);
  validateWidth(width);

  const lines = [];
  for (const piece of text.split('\n')) {
    lines.push(...wrapPiece(piece, width));
  }
  return lines;
}

/**
 * Pad a single line to an exact display width.
 *
 * @param {string} text Line that already fits.
 * @param {number} width Target column width.
 * @param {'left'|'right'|'center'} [align] Alignment, left by default.
 * @returns {string} Padded line.
 */
export function padCell(text, width, align = 'left') {
  validateCell(text);
  validateWidth(width);

  if (align !== 'left' && align !== 'right' && align !== 'center') {
    throw new TableError('BAD_ALIGN', `unknown alignment: ${align}`);
  }

  const contentWidth = stringWidth(text);
  if (contentWidth > width) {
    throw new TableError('CELL_TOO_WIDE', 'content is wider than the column');
  }

  const padding = width - contentWidth;
  if (align === 'right') {
    return `${' '.repeat(padding)}${text}`;
  }
  if (align === 'center') {
    const leftPadding = Math.floor(padding / 2);
    return `${' '.repeat(leftPadding)}${text}${' '.repeat(padding - leftPadding)}`;
  }
  return `${text}${' '.repeat(padding)}`;
}

/**
 * Render rows as a fixed-width table.
 *
 * @param {string[][]} rows Rows of cells.
 * @param {{widths: number[], align?: string[], header?: boolean}} options Layout options.
 * @returns {string} Table text without a trailing newline.
 */
export function formatTable(rows, options) {
  if (options === null || typeof options !== 'object') {
    throw new TableError('BAD_OPTIONS', 'options must be an object');
  }

  const widths = options.widths;
  if (
    !Array.isArray(widths) ||
    widths.length === 0 ||
    widths.some((width) => !Number.isInteger(width) || width < 1)
  ) {
    throw new TableError('BAD_WIDTH', 'widths must be a non-empty array of positive integers');
  }

  const alignments = [];
  if (options.align !== undefined) {
    if (!Array.isArray(options.align) || options.align.length !== widths.length) {
      throw new TableError('BAD_ALIGN', `align must have ${widths.length} entries`);
    }
    for (const alignment of options.align) {
      if (alignment !== 'left' && alignment !== 'right' && alignment !== 'center') {
        throw new TableError('BAD_ALIGN', `unknown alignment: ${alignment}`);
      }
      alignments.push(alignment);
    }
  } else {
    alignments.push(...Array(widths.length).fill('left'));
  }

  if (!Array.isArray(rows)) {
    throw new TableError('BAD_ROWS', 'rows must be an array');
  }

  for (let rowIndex = 0; rowIndex < rows.length; rowIndex += 1) {
    const row = rows[rowIndex];
    const cellCount = Array.isArray(row) ? row.length : 0;
    if (cellCount !== widths.length) {
      throw new TableError(
        'BAD_ROW_LENGTH',
        `row ${rowIndex} has ${cellCount} cells, expected ${widths.length}`,
      );
    }

    for (let columnIndex = 0; columnIndex < widths.length; columnIndex += 1) {
      validateCell(row[columnIndex]);
    }
  }

  if (rows.length === 0) {
    return '';
  }

  const outputLines = [];
  for (let rowIndex = 0; rowIndex < rows.length; rowIndex += 1) {
    const wrappedCells = rows[rowIndex].map((cell, columnIndex) =>
      wrapCell(cell, widths[columnIndex]),
    );
    const rowHeight = Math.max(...wrappedCells.map((cellLines) => cellLines.length));

    for (let lineIndex = 0; lineIndex < rowHeight; lineIndex += 1) {
      const paddedCells = wrappedCells.map((cellLines, columnIndex) => {
        const cellLine = lineIndex < cellLines.length ? cellLines[lineIndex] : '';
        return padCell(cellLine, widths[columnIndex], alignments[columnIndex]);
      });
      outputLines.push(paddedCells.join(' | '));
    }

